mapper.select:
SELECT v.*, COALESCE(c.category_code, 'OTHER') category_code FROM tb_variable_version v
INNER JOIN (SELECT variable_code, MAX(version_number) version_number
            FROM tb_variable_version WHERE isactive = 1 GROUP BY variable_code) latest
  ON latest.variable_code = v.variable_code AND latest.version_number = v.version_number
LEFT JOIN tb_variable_category c ON c.variable_code = v.variable_code AND c.isactive = 1
WHERE v.isactive = 1 AND (v.variable_code LIKE #{pattern} OR v.variable_name LIKE #{pattern})
AND COALESCE(c.category_code, 'OTHER') = #{categoryCode}
AND v.source_type = #{sourceType}
AND v.value_type = #{valueType}
ORDER BY v.variable_code ASC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM (SELECT variable_code, MAX(version_number) version_number
    FROM tb_variable_version WHERE isactive = 1 GROUP BY variable_code) latest
INNER JOIN tb_variable_version v
  ON latest.variable_code = v.variable_code AND latest.version_number = v.version_number
LEFT JOIN tb_variable_category c ON c.variable_code = v.variable_code AND c.isactive = 1
WHERE v.isactive = 1 AND (v.variable_code LIKE #{pattern} OR v.variable_name LIKE #{pattern})
AND COALESCE(c.category_code, 'OTHER') = #{categoryCode}
AND v.source_type = #{sourceType}
AND v.value_type = #{valueType}
